}$catalog$::jsonb AS data),
expected AS (
 SELECT t.key AS collection, r.row, COALESCE(r.row->>'facultyKey',r.row->>'departmentKey') AS unused
 FROM document, jsonb_each(data) t CROSS JOIN LATERAL jsonb_array_elements(CASE WHEN jsonb_typeof(t.value)='array' THEN t.value ELSE '[]'::jsonb END) r(row)
), actual AS (
 SELECT 'faculties' AS collection, f."ImportKey" AS key, to_jsonb(f)||jsonb_build_object('FacultyKey',f."ImportKey") AS row FROM "Faculties" f
 UNION ALL SELECT 'departments',d."DepartmentKey",to_jsonb(d)||jsonb_build_object('FacultyKey',f."ImportKey") FROM "Departments" d JOIN "Faculties" f USING("FacultyId")
 UNION ALL SELECT 'instructors',i."ImportKey",to_jsonb(i)||jsonb_build_object('InstructorKey',i."ImportKey",'DepartmentKey',d."DepartmentKey") FROM "Instructors" i JOIN "Departments" d USING("DepartmentId")
 UNION ALL SELECT 'programmes',p."ProgrammeKey",to_jsonb(p)||jsonb_build_object('DepartmentKey',d."DepartmentKey") FROM "Programmes" p JOIN "Departments" d USING("DepartmentId")
 UNION ALL SELECT 'courses',c."CourseKey",to_jsonb(c)||jsonb_build_object('DepartmentKey',d."DepartmentKey") FROM "Courses" c JOIN "Departments" d USING("DepartmentId")
 UNION ALL SELECT 'programmeCourses',pc."CurriculumKey",to_jsonb(pc)||jsonb_build_object('ProgrammeKey',p."ProgrammeKey",'CourseKey',c."CourseKey") FROM "ProgrammeCourses" pc JOIN "Programmes" p USING("ProgrammeId") JOIN "Courses" c USING("CourseId")
), keyed AS (
 SELECT e.*, e.row->>CASE collection WHEN 'faculties' THEN 'facultyKey' WHEN 'departments' THEN 'departmentKey' WHEN 'instructors' THEN 'instructorKey' WHEN 'programmes' THEN 'programmeKey' WHEN 'courses' THEN 'courseKey' ELSE 'curriculumKey' END AS key FROM expected e
), mismatches AS (
 SELECT e.collection,e.key,f.key AS field, f.value expected, a.row->(upper(left(f.key,1))||substring(f.key,2)) actual
 FROM keyed e LEFT JOIN actual a USING(collection,key) CROSS JOIN LATERAL jsonb_each(e.row) f
 WHERE f.value IS DISTINCT FROM a.row->(upper(left(f.key,1))||substring(f.key,2))
)
SELECT collection,key,field,expected,actual FROM mismatches ORDER BY collection,key,field;
